require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';tt_require_login();$user=(string)$_SESSION['name'];$id=(int)$_SESSION['id'];$db=tt_db_open(true);$adsReady=tt_ad_schema_ready($db);$hitsReady=tt_schema_table_exists($db,'post_impressions');try{tt_opportunistic_maintenance($db);tt_federation_tick($db);}catch(Throwable $e){}
$s=tt_prepare($db,'SELECT `aboutcontent`,`tags` FROM `accounts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($about,$myTags);$s->fetch();$s->close();
$stats=['posts'=>0,'impressions'=>0,'rated_posts'=>0,'karma_ratings'=>0,'moksha'=>0,'moksha_ratings'=>0,'top_karma'=>0,'overall_karma'=>0];$topHit=null;$topKarma=null;$postRatingsReady=tt_schema_table_exists($db,'post_ratings');
$s=tt_prepare($db,'SELECT COUNT(*) FROM `posts` WHERE `name`=?');$s->bind_param('s',$user);$s->execute();$s->bind_result($stats['posts']);$s->fetch();$s->close();$stats['posts']=(int)$stats['posts'];
if($hitsReady){$s=tt_prepare($db,'SELECT COUNT(*) FROM `post_impressions` pi JOIN `posts` p ON p.`id`=pi.`post_id` WHERE p.`name`=?');$s->bind_param('s',$user);$s->execute();$s->bind_result($stats['impressions']);$s->fetch();$s->close();$stats['impressions']=(int)$stats['impressions'];$s=tt_prepare($db,'SELECT p.`id`,p.`title`,COUNT(*) n FROM `post_impressions` pi JOIN `posts` p ON p.`id`=pi.`post_id` WHERE p.`name`=? GROUP BY p.`id`,p.`title` ORDER BY n DESC,p.`id` DESC LIMIT 1');$s->bind_param('s',$user);$s->execute();$topHit=$s->get_result()->fetch_assoc();$s->close();}
// Moksha belongs to the user profile; Karma belongs to posts.

if(tt_schema_table_exists($db,'account_ratings')){$s=tt_prepare($db,'SELECT ROUND(AVG(`perspective`)),COUNT(*) FROM `account_ratings` WHERE `target_account_id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($stats['moksha'],$stats['moksha_ratings']);$s->fetch();$s->close();$stats['moksha']=(int)($stats['moksha']??0);$stats['moksha_ratings']=(int)($stats['moksha_ratings']??0);}
if($postRatingsReady){$kq='SELECT p.`id`,p.`title`,ROUND(AVG(pr.`perspective`)) karma,COUNT(*) ratings FROM `posts` p JOIN `post_ratings` pr ON pr.`post_id`=p.`id` WHERE p.`name`=? GROUP BY p.`id`,p.`title` ORDER BY AVG(pr.`perspective`) DESC,ratings DESC,p.`id` DESC LIMIT 1';$s=tt_prepare($db,$kq);$s->bind_param('s',$user);$s->execute();$topKarma=$s->get_result()->fetch_assoc();$s->close();$stats['top_karma']=$topKarma?(int)$topKarma['karma']:0;$oq='SELECT ROUND(AVG(COALESCE(k.`karma`,0))) overall_karma,COALESCE(SUM(CASE WHEN COALESCE(k.`ratings`,0)>0 THEN 1 ELSE 0 END),0) rated_posts,COALESCE(SUM(COALESCE(k.`ratings`,0)),0) karma_ratings FROM `posts` p LEFT JOIN (SELECT `post_id`,AVG(`perspective`) karma,COUNT(*) ratings FROM `post_ratings` GROUP BY `post_id`) k ON k.`post_id`=p.`id` WHERE p.`name`=?';$s=tt_prepare($db,$oq);$s->bind_param('s',$user);$s->execute();$s->bind_result($stats['overall_karma'],$stats['rated_posts'],$stats['karma_ratings']);$s->fetch();$s->close();$stats['overall_karma']=(int)($stats['overall_karma']??0);$stats['rated_posts']=(int)($stats['rated_posts']??0);$stats['karma_ratings']=(int)($stats['karma_ratings']??0);}
$ads=[];if($adsReady){$tagTokens=array_values(array_filter(array_map('trim',preg_split('/[;,]+/',(string)$myTags)?:[])));$adSql="SELECT p.`id`,p.`title`,p.`content`,p.`file`,p.`type`,p.`tags`,pa.`mime_type` AS attachment_mime,ab.`id` AS boost_id FROM `ad_boosts` ab JOIN `posts` p ON p.`id`=ab.`post_id` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` WHERE ab.`status`='active' AND ab.`budget_mills`>ab.`spent_mills` AND ab.`buyer_account_id`<>? AND (ab.`target_username`=? OR ab.`target_username`=''";$ap=[$id,$user];$at='is';if($tagTokens){$likes=[];foreach(array_slice($tagTokens,0,8) as $t){$likes[]='ab.`target_tags` LIKE ?';$ap[]='%'.$t.'%';$at.='s';}$adSql.=' OR '.implode(' OR ',$likes);}$adSql.=') ORDER BY (ab.`target_username`=?) DESC,(ab.`budget_mills`-ab.`spent_mills`) DESC LIMIT 8';$ap[]=$user;$at.='s';$x=tt_prepare($db,$adSql);$x->bind_param($at,...$ap);$x->execute();$ads=$x->get_result()->fetch_all(MYSQLI_ASSOC);$x->close();}
[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`name`,p.`scope`,p.`type`,p.`file` FROM `posts` p WHERE '.$vis.' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 30';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$homeKarma=[];if($postRatingsReady&&$rows){$ids=implode(',',array_map(fn($r)=>(int)$r['id'],$rows));$kr=$db->query('SELECT `post_id`,ROUND(AVG(`perspective`)) karma,COUNT(*) ratings FROM `post_ratings` WHERE `post_id` IN ('.$ids.') GROUP BY `post_id`');while($kr&&($kx=$kr->fetch_assoc()))$homeKarma[(int)$kx['post_id']]=['karma'=>(int)$kx['karma'],'ratings'=>(int)$kx['ratings']];if($kr)$kr->free();}foreach($rows as &$r){$rk=$homeKarma[(int)$r['id']]??['karma'=>0,'ratings'=>0];$r['_karma']=$rk['karma'];$r['_karma_count']=$rk['ratings'];}unset($r);$postDelay=tt_delay_status($db,'post',$id);$messageDelay=tt_delay_status($db,'message',$id);$db->close();
function tt_signed_stat($v):string{$v=(int)$v;return ($v>=0?'+':'').$v;}function tt_home_delay_text(array $d):string{if(!empty($d['infinite']))return '∞';$left=(int)($d['remaining']??0);if($left<=0)return 'Ready · '.tt_delay_human((int)($d['duration']??0));return tt_delay_human($left).' remaining · current '.tt_delay_human((int)($d['duration']??0));}
