<h2>Your stats</h2><section class="grid user-stats"><article class="card"><h3>Time delay</h3><p><strong>Post:</strong> <?=tt_h(tt_home_delay_text($postDelay))?></p><p><strong>Message:</strong> <?=tt_h(tt_home_delay_text($messageDelay))?></p><p class="meta">Failed attempts can increase the timer; your profile Moksha participates in the account action-delay formula.</p></article><article class="card"><h3>Posts</h3><p class="stat-number"><?=number_format($stats['posts'])?></p></article><article class="card"><h3>Post impressions / hits</h3><p class="stat-number"><?=$hitsReady?number_format($stats['impressions']):'—'?></p><p class="meta"><?=$hitsReady?($topHit?'Top: #'.(int)$topHit['id'].' · '.tt_h($topHit['title']).' · '.number_format((int)$topHit['n']).' hits':'No counted hits yet.'):'Run the protected schema maintenance once to enable hit tracking.'?></p></article><article class="card"><h3>Your Moksha</h3><p class="stat-number"><?=tt_signed_stat($stats['moksha'])?> / 256</p><p class="meta"><?=number_format($stats['moksha_ratings'])?> profile rating<?=($stats['moksha_ratings']===1?'':'s')?>. <a href="profile.php?user=<?=urlencode($user)?>">View your profile</a></p></article><article class="card"><h3>Top Karma</h3><p class="stat-number"><?=$postRatingsReady?tt_signed_stat($stats['top_karma']).' / 256':'—'?></p><p class="meta"><?=$postRatingsReady?($topKarma?'Average on #'.(int)$topKarma['id'].' · '.tt_h($topKarma['title']).' · '.(int)$topKarma['ratings'].' rating'.((int)$topKarma['ratings']===1?'':'s'):'No post ratings yet.'):'Run protected schema maintenance once to enable Karma tracking.'?></p></article><article class="card"><h3>Overall post Karma</h3><p class="stat-number"><?=$postRatingsReady?tt_signed_stat($stats['overall_karma']).' / 256':'—'?></p><p class="meta"><?=$postRatingsReady?number_format($stats['rated_posts']).' rated post'.($stats['rated_posts']===1?'':'s').' · '.number_format($stats['karma_ratings']).' total rating'.($stats['karma_ratings']===1?'':'s').' across '.number_format($stats['posts']).' post'.($stats['posts']===1?'':'s'):'Karma tracking is not enabled on this database yet.'?></p></article></section>
<?php if($ads):?><h2>Sponsored / boosted for your page</h2><section class="grid ad-grid"><?php foreach($ads as $a):?><article class="card ad-card"<?=tt_nsfw_attr((string)$a['title'],(string)($a['tags']??''))?> data-boost-id="<?=(int)$a['boost_id']?>" data-page-owner-id="<?=$id?>"><p class="meta">Sponsored · 1 natural credit = 1 counted impression; Square-funded impressions can also fund Earnings</p><h3><a href="post.php#post-<?=(int)$a['id']?>"><?=tt_h($a['title'])?></a></h3><p><?=nl2br(tt_h($a['content']))?></p><?=tt_ad_attachment_html($a)?></article><?php endforeach;?></section><?php endif;?><h2>Latest relevant posts</h2><section class="grid"><?php foreach($rows as $r):?><article class="card post-card"<?=tt_nsfw_attr((string)$r['title'],(string)$r['tags'])?> data-post-expandable="1" data-post-impression-id="<?=(int)$r['id']?>" aria-expanded="false"><h3><a href="post.php#post-<?=(int)$r['id']?>"><?=tt_h($r['title'])?></a></h3><p class="meta"><?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?> · <?=tt_h(trim($r['scope']))?> · <?=tt_h(tt_canonical_post_type((string)$r['type']))?></p><?php if($postRatingsReady):?><div class="karma-summary"><strong>Karma:</strong> <?=tt_signed_stat((int)$r['_karma'])?> / 256 · <?=(int)$r['_karma_count']?> rating<?=((int)$r['_karma_count']===1?'':'s')?></div><?php endif;?><p><?=nl2br(tt_h(mb_strimwidth((string)$r['content'],0,600,'…','UTF-8')))?></p><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>">Attachment</a></p><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><article class="card"><p>No visible posts yet. <a href="create.php">Create the first one.</a></p></article><?php endif;?></section></main><script>document.querySelectorAll('[data-boost-id]').forEach(el=>{const f=new FormData();f.set('boost_id',el.dataset.boostId);f.set('page_owner_id',el.dataset.pageOwnerId||'0');fetch('ad_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});document.querySelectorAll('[data-post-impression-id]').forEach(el=>{const f=new FormData();f.set('post_id',el.dataset.postImpressionId);fetch('post_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});</script>
